// Function to calculate the acceleration of the pendulum
function calcAccel() {
  // Calculate the angle of the pendulum from the vertical
  const theta = angle * ANGLE_FACTOR;

  // Calculate the acceleration using thePhysics of gravity and the pendulum length
  const accel = -(GRAVITY * PENDULUM_LENGTH / (1 + Math.sin(theta) ** 2));

  return accel;
}

// Function to update the pendulum position and velocity
