  // Calculate the acceleration using the previously calculated angle and velocity
  const accel = calcAccel();

  // Update the velocity using the acceleration and the time step
  velocity += accel * timestep;

  // Update the angle using the velocity and the time step
  angle += velocity * timestep;

  // Accumulate time
  accumTime += timestep;
}

